        best = None
        min_dist = float('inf')
        for move in next_moves:
            dist = abs(move[0] - goal[0]) + abs(move[1] - goal[1])
            if dist < min_dist:
                min_dist = dist
                best = move
        current = best
        path.append(current)
        if current == goal:
